arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -H 'Content-Type: application/json' -d '{"token":"***","channel":"C_REL","limit":500}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR', d)
else:
    print('total messages:', len(d.get('messages',[])))
    for m in d.get('messages',[]):
        t=m.get('text','')
        if 'release' in t.lower() and 'cut' in t.lower():
            print(json.dumps(m, default=str)[:500])
"

